def shot_predict(feats):
    """Return raw logit. Probability = 1/(1+exp(-logit))."""
    z = SHOT_INIT
    for feat, thr, val, left, right in SHOT_TREES:
        node = 0
        while feat[node] >= 0:
            if feats[feat[node]] <= thr[node]:
                node = left[node]
            else:
                node = right[node]
        z += val[node]
    return z